/* tpg_zio — NTSC test pattern generator for the FreeWili 2, as a display app.
 *
 * Port of the FreeWili OG TPG (apps/tpg): the same 262-line NTSC timing and
 * the same nine patterns, in the same order (common/tpg_patterns.h). On the
 * OG the main CPU's PIO generates the video; here each pattern is a
 * cycle-counted ZoomIO program (generated by gen_tpg_zio.py into
 * tpg_zio_scripts.h) that the stock MAIN firmware compiles and runs on its
 * RISC-V core1. Neither CPU's flash is touched.
 *
 * Output on the 20-pin header, the same GPIOs on the same pins as the OG TPG,
 * so one cable fits both boards:
 *
 *   B0 B1 B2   GPIO  8  9 10   header  9  5  7
 *   G0 G1 G2   GPIO 11 12 13   header 11 12  1
 *   R0 R1 R2   GPIO 14 15 26   header 15 13 14
 *   CSYNC      GPIO 27         header  3        (active low)
 *
 * The header's level shifters have their own direction, and GPIO 9, 10, 12
 * and 26 default to inputs, so the app sets all ten to outputs; without that
 * those bits toggle inside MAIN but never reach the header. The direction is
 * one of MAIN's settings, so it outlives the app.
 *
 * At start the app selects the 3.3 V VIO rail, holds power zone 6 (FPGA,
 * which run_zio requires), writes all nine programs to /appdata/tpg_zio/ and
 * runs the first. Switching then costs a stop and a run, no SD writes.
 * MAIN gates ZoomIO on the zone state DISPLAY reports, so the app keeps
 * reporting it (see the zio_probe app).
 *
 * GREEN next pattern, YELLOW previous, RED stop / run. HOLD HOME 5 S leaves
 * the app but not the pattern: core1 keeps generating it until MAIN is told
 * to stop or reboots. */
#include "fw2.h"
#include "platform/diag.h"
#include "pico/stdlib.h"
#include "onewili.h"
#include "onewili_fwgui.h"
#include "onewili_sd.h"
#include "input/app_recovery_onewili.h"
#include "common/tpg_patterns.h"
#include "tpg_zio_scripts.h"
#include <stdarg.h>
#include <stdio.h>
#include <string.h>

#define APP_DIR "/appdata/tpg_zio"

static const uint8_t pins[] = TPG_ZIO_PINS;
#define N_PINS (int)(sizeof pins / sizeof pins[0])

/* ~37 KB of link buffers — far too big for the 2 KB stack. */
static ow_device dev;

static tpg_pattern_id_t pattern = TPG_PATTERN_COLOR_BARS;
static bool running;

static inline uint16_t be16(uint16_t c) {
    return (uint16_t)((c >> 8) | (c << 8));
}

#define C_BLACK be16(0x0000)
#define C_WHITE be16(0xFFFF)
#define C_GREEN be16(0x07E0)
#define C_RED   be16(0xF800)
#define C_GREY  be16(0x8410)

/* Status rows at scale 2 (16 px glyphs, 29 columns inside the margins),
 * below the pattern name. */
enum { ROW_STATE, ROW_REPLY, ROW_REPLY2, ROW_LINK, ROW_POWER, ROW_COUNT };
#define ROW_Y(r) (120 + (r) * 26)
#define NAME_Y   48

static void line(int row, uint16_t fg, const char *fmt, ...) {
    char s[30];
    va_list ap;
    va_start(ap, fmt);
    vsnprintf(s, sizeof s, fmt, ap);
    va_end(ap);
    st7796_fill_rect(8, ROW_Y(row), 464, 16, C_BLACK);
    st7796_draw_text(8, ROW_Y(row), 2, fg, C_BLACK, s);
}

/* The pattern name at scale 4 (24 x 32 px glyphs: 19 columns) with its
 * position in the cycle. */
static void show_pattern(void) {
    char n[8];
    st7796_fill_rect(8, NAME_Y, 464, 64, C_BLACK);
    st7796_draw_text(8, NAME_Y, 4, C_WHITE, C_BLACK, tpg_pattern_name(pattern));
    snprintf(n, sizeof n, "%d/%d", (int)pattern + 1, TPG_PATTERN_COUNT);
    st7796_draw_text(8, NAME_Y + 40, 2, C_GREY, C_BLACK, n);
}

/* Bottom-row labels, one fifth per button (wilibsp AGENTS.md), grey and blue
 * slots left empty because those buttons do nothing here. */
static void button_bar(void) {
    const int w = (ST7796_W - 12) / 5, h = 34, y = ST7796_H - h;
    st7796_fill_rect(1 * 96, y, w, h, 0x06FF);   /* yellow, wire order */
    st7796_draw_text(1 * 96 + 14, y + 9, 2, C_BLACK, 0x06FF, "PREV");
    st7796_fill_rect(2 * 96, y, w, h, 0x0012);   /* green, wire order */
    st7796_draw_text(2 * 96 + 14, y + 9, 2, C_WHITE, 0x0012, "NEXT");
    st7796_fill_rect(4 * 96, y, w, h, 0x0780);   /* red, wire order */
    st7796_draw_text(4 * 96 + 8, y + 9, 2, C_WHITE, 0x0780, running ? "STOP" : "RUN");
}

/* MAIN's reply body across two rows (it is free text on failure). */
static void show_reply(const char *reply, bool ok) {
    char a[30] = "", b[30] = "";
    if (ok) {
        line(ROW_REPLY, C_BLACK, "");
        line(ROW_REPLY2, C_BLACK, "");
        return;
    }
    snprintf(a, sizeof a, "%s", reply[0] ? reply : "(ERR, NO TEXT)");
    if (strlen(reply) > 29) snprintf(b, sizeof b, "%s", reply + 29);
    line(ROW_REPLY, C_RED, "%s", a);
    line(ROW_REPLY2, C_RED, "%s", b);
}

/* Send one menu command through the raw path so MAIN's reply text survives:
 * the generated bindings report only OK / FAILED, and a failure's text
 * (compile errors, EPOWERZONE, ...) is what the user needs to see. With
 * quiet set, a failure is logged but not shown (expected failures). */
static bool call(const char *label, const char *cmd, bool quiet) {
    static char reply[OW_RESP_MAX];
    int ok = 0;
    ow_raw_stash_clear();
    if (ow_raw_send(&dev, cmd) < 0) {
        DIAG("tpg_zio: %s send failed\n", label);
        if (!quiet) show_reply("SEND FAILED", false);
        return false;
    }
    ow_status s = ow_raw_next_response(&dev, reply, sizeof reply, &ok, 10000);
    if (s != OW_OK) {
        DIAG("tpg_zio: %s no response, status %d\n", label, (int)s);
        if (!quiet) show_reply(s == OW_ERR_TIMEOUT ? "NO REPLY (TIMEOUT)" : "NO REPLY (LINK ERROR)", false);
        return false;
    }
    DIAG("tpg_zio: %s ok=%d reply '%s'\n", label, ok, reply);
    if (!quiet) show_reply(reply, ok != 0);
    return ok != 0;
}

/* MAIN gates header GPIO and ZoomIO on zone 6 using the zone state DISPLAY
 * reports (event 48). The stock DISPLAY firmware sends that; a RAM app that
 * replaced it must too, or MAIN keeps refusing with EPOWERZONE 6 FPGA. */
static void report_zones(void) {
    uint32_t rails;
    if (picpwr_rails(&rails)) ow_fwgui_send_power_zones(rails);
}

/* Header GPIO -> its item in MAIN's IO Directions menu (i\g\a). The items are
 * documented as toggles, but take an optional value: 1 = out, 0 = in. That
 * makes setting a direction idempotent, so it needs no read-back. */
static char dir_key(int gpio) {
    switch (gpio) {
    case 8:  return 'g';
    case 9:  return 'e';
    case 10: return 'f';
    case 11: return 'm';
    case 12: return 'a';
    case 13: return 'c';
    case 14: return 'j';
    case 15: return 'i';
    case 25: return 'k';
    case 26: return 'b';
    case 27: return 'l';
    default: return 0;
    }
}

/* Every pin becomes a plain SIO output, low (so ZoomIO's setiodir/setio take
 * over cleanly and a stopped TPG outputs black with sync held), and its
 * header level shifter an output. Repeated before each run in case MAIN has
 * rebooted. */
static bool pins_out_low(void) {
    char cmd[16];
    for (int i = 0; i < N_PINS; i++) {
        snprintf(cmd, sizeof cmd, "i\\g\\l %d", pins[i]);
        if (!call("GPIO LOW", cmd, false)) return false;
        snprintf(cmd, sizeof cmd, "i\\g\\a\\%c 1", dir_key(pins[i]));
        if (!call("HEADER OUT", cmd, false)) return false;
    }
    return true;
}

static void stop(void) {
    (void)call("STOP_ZIO", "s\\b\\s", true);   /* fails harmlessly if nothing runs */
    (void)pins_out_low();
    running = false;
    line(ROW_STATE, C_GREY, "STOPPED, OUTPUTS LOW");
    button_bar();
}

static void run(void) {
    char cmd[64];
    show_pattern();
    line(ROW_STATE, C_WHITE, "STARTING...");
    report_zones();
    fw2_app_recovery_sleep_ms(100);   /* fire-and-forget: let MAIN apply it */
    (void)call("STOP_ZIO", "s\\b\\s", true);
    running = false;
    /* HSBDIO would make GPIO 27 (CSYNC) the direction control for GPIO 26. */
    if (call("HSBDIO OFF", "i\\g\\e 0", false) && pins_out_low()) {
        snprintf(cmd, sizeof cmd, "s\\b\\r " APP_DIR "/%s", TPG_ZIO[pattern].file);
        running = call("RUN_ZIO", cmd, false);
    }
    line(ROW_STATE, running ? C_GREEN : C_RED, running ? "RUNNING" : "RUN FAILED");
    button_bar();
}

/* One file, in single-chunk pieces. ow_sd_put_mem sends a multi-chunk file
 * without per-chunk acknowledgement, and over the display link a chunk can be
 * dropped (OW_ERR_PROTOCOL: the server saw a gap). Each piece of at most
 * SDFS_MAX_PAYLOAD bytes is confirmed on its own; any failure restarts the
 * file, since its first piece truncates. */
static ow_status put_file(const char *path, const char *text) {
    const size_t len = strlen(text);
    ow_status s = OW_OK;
    for (int attempt = 0; attempt < 3; attempt++) {
        size_t off = 0;
        do {
            const size_t n = len - off < SDFS_MAX_PAYLOAD ? len - off : SDFS_MAX_PAYLOAD;
            s = ow_sd_put_mem(&dev, path, text + off, n, off != 0);
            off += n;
        } while (s == OW_OK && off < len);
        if (s == OW_OK) return OW_OK;
        DIAG("tpg_zio: put %s attempt %d failed at %u: status %d (sdfs %d)\n",
             path, attempt + 1, (unsigned)off, (int)s, (int)ow_sd_last_error());
    }
    return s;
}

/* Write all nine programs; MAIN compiles from the SD card. Rewritten every
 * start, so the card always matches this build. */
static bool install(void) {
    (void)ow_sd_mkdir(&dev, "/appdata");   /* exist after the first run */
    (void)ow_sd_mkdir(&dev, APP_DIR);
    for (int i = 0; i < TPG_PATTERN_COUNT; i++) {
        char path[64];
        line(ROW_STATE, C_WHITE, "WRITING PROGRAM %d/%d", i + 1, TPG_PATTERN_COUNT);
        snprintf(path, sizeof path, APP_DIR "/%s", TPG_ZIO[i].file);
        const ow_status s = put_file(path, TPG_ZIO[i].zio);
        if (s != OW_OK) {
            line(ROW_STATE, C_RED, "SD WRITE %d FAILED (%d)", i + 1, (int)s);
            return false;
        }
    }
    return true;
}

/* Hold the FPGA rail and wait (bounded) until the coprocessor reports it. */
static bool fpga_zone_up(void) {
    const uint32_t bit = picpwr_zone_bit(PICPWR_ZONE_FPGA);
    picpwr_keep_awake(bit);
    for (uint32_t waited = 0; waited < 5000; waited += 10) {
        uint32_t rails = 0;
        if (picpwr_rails(&rails) && (rails & bit)) return true;
        fw2_app_recovery_sleep_ms(10);
    }
    return false;
}

int main(void) {
    board_init();   /* must precede ow_open_fwgui: uart_init reads clk_peri */
    fw2_app_recovery_init();
    st7796_init();
    fw2_app_about_use_lcd();
    agentio_init();   /* before the first clear: it owns the capture shadow */
    st7796_fill_screen(C_BLACK);
    st7796_draw_text(8, 8, 2, C_WHITE, C_BLACK, "TPG  NTSC 240P  ZOOMIO");
    show_pattern();
    button_bar();
    board_backlight_set(1);
    ioexp_vref(VREF_3V3);   /* required: no VIO rail => the header pins cannot drive */

    line(ROW_POWER, C_WHITE, "FPGA ZONE 6...");
    const bool fpga = fpga_zone_up();
    picpwr_release_unused();
    DIAG("tpg_zio: FPGA zone %s\n", fpga ? "up" : "NOT reported up");
    line(ROW_POWER, fpga ? C_GREY : C_RED, "FPGA ZONE 6 %s", fpga ? "ON" : "NOT ON");

    line(ROW_LINK, C_WHITE, "CONNECTING TO MAIN...");
    while (fw2_app_recovery_open_onewili(&dev) != OW_OK) {
        fw2_app_recovery_task();
        DIAG("tpg_zio: FwGUI link open failed (is the main CPU running stock fw?), retry in 1 s\n");
        line(ROW_LINK, C_RED, "MAIN LINK FAILED, RETRY");
        fw2_app_recovery_sleep_ms(1000);
    }
    if (fw2_app_recovery_wrap_sd() != OW_OK) {
        DIAG("tpg_zio: recovery-aware SD transport setup failed\n");
        line(ROW_LINK, C_RED, "SD TRANSPORT SETUP FAILED");
    } else {
        line(ROW_LINK, C_GREY, "MAIN LINK UP");
    }

    if (install()) run();

    uint64_t next_report_us = 0;
    for (;;) {
        fw2_app_recovery_task();
        agentio_task();

        uartkbd_event_t ev;
        while (uartkbd_next_event(&ev)) {
            if (!ev.pressed) continue;
            if (ev.btn == UARTKBD_BTN_GREEN) {
                pattern = (tpg_pattern_id_t)((pattern + 1u) % TPG_PATTERN_COUNT);
                run();
            } else if (ev.btn == UARTKBD_BTN_YELLOW) {
                pattern = (tpg_pattern_id_t)((pattern + TPG_PATTERN_COUNT - 1u) % TPG_PATTERN_COUNT);
                run();
            } else if (ev.btn == UARTKBD_BTN_RED) {
                if (running) stop();
                else run();
            }
        }

        if (time_us_64() >= next_report_us) {
            report_zones();   /* MAIN may have rebooted: keep it informed */
            next_report_us = time_us_64() + 1000000u;
        }
        fw2_app_recovery_sleep_ms(10);
    }
}
